343	// REHEARSAL MODE (per-project-scheduling rehearsal, #593 phase 0). A run may be
344	// pointed at a canon BRANCH instead of its default head, so a canon change can be
345	// tried against a real repo before it merges. `CLAUDINITE_CANON_REF` selects the
346	// ref; `CLAUDINITE_CANON_URL` a fork.
347	//
348	// The stamp is the whole reason this needs its own decision rather than an extra
349	// clone argument. A branch head is NOT on trunk, and stamping it is precisely the
350	// shape vendoring's #328 anti-rewind guard refuses to write over afterwards
351	// (`ref-not-on-trunk`, which the sheepdog freshness sweep reads as WEDGED, not
352	// late) — a rehearsal would leave the repo unable to baseline ever again. This
353	// was not hypothetical: it happened by hand on 2026-07-30, to all thirteen
354	// members at once, from a converge run out of an unmerged branch.
355	//
356	// So a rehearsal stamps NOTHING. It converges, it reports, and it leaves the
357	// member's provenance exactly as it found it.
358	export function canonSource(env = {}) {
359	  const ref = String(env.CLAUDINITE_CANON_REF ?? '').trim();
360	  const url = String(env.CLAUDINITE_CANON_URL ?? '').trim() || CANON_URL;
361	  return { url, ref: ref || null, rehearsal: Boolean(ref) };
