507	// Run the engine's self-test against the converged tree; green when the machinery
508	// is intact. Same soft shape as runCheckTheWorld — a missing selftest (an older
509	// mount that predates it) is not a failure, it is nothing to run.
510	function runSelfTest(root) {
511	  const st = join(root, '.claudinite/shared/engine/selftest.mjs');
512	  if (!existsSync(st)) return GATE_ABSENT;
513	  try { node([st, '--strict'], { CLAUDE_PROJECT_DIR: root }); return gateOutcome(null); }
514	  catch (e) { return gateOutcome(e); }
515	}
