517	// What a gate said, for the LOG — the full text, not a summary. This is the one
518	// place the findings belong: the Action log is an observability surface nothing
519	// reads programmatically, so it carries everything, while the dispatch issue
520	// carries only the condition (preprocess.mjs, the §3 exception).
521	function logGateOutput(label, outcome) {
522	  const body = outcome.output ? `\n${outcome.output}` : ' (no output)';
523	  console.log(`baselining: ${label} ${outcome.crashed ? 'COULD NOT RUN' : `exited ${outcome.status}`} —${body}`);
524	}
