734	// The I/O half of the CI dispatch (#565): read the workflow files as they exist
735	// ON THE MAINTENANCE BRANCH (the converge may itself have changed them), plan
736	// with ciDispatchPlan, POST a dispatch per selected workflow, and log every
737	// outcome — a silent no-checks PR is exactly the failure mode this exists to
738	// close. Needs the scheduler workflow's `actions: write` (a read-only token
739	// 403s the POST silently — the store-release lesson).
740	async function dispatchCiRuns(token, repo, branch) {
741	  const ref = encodeURIComponent(branch);
742	  const { json: dir } = await gh(token, `/repos/${repo}/contents/.github/workflows?ref=${ref}`);
743	  const files = [];
744	  for (const entry of Array.isArray(dir) ? dir : []) {
745	    if (!/\.ya?ml$/.test(entry.name ?? '')) continue;
746	    const { json } = await gh(token, `/repos/${repo}/contents/.github/workflows/${entry.name}?ref=${ref}`);
747	    files.push({ name: entry.name, content: json?.content ? Buffer.from(json.content, 'base64').toString('utf8') : '' });
748	  }
749	  const { dispatch, missing } = ciDispatchPlan(files);
750	  for (const name of missing) {
751	    console.log(`baselining: ${name} runs on pull_request but has no workflow_dispatch trigger — `
752	      + 'cannot start it on the maintenance PR; add `workflow_dispatch:` under its `on:` to let baselining run it');
753	  }
754	  if (!dispatch.length && !missing.length) {
755	    console.log('baselining: no pull_request-triggered workflow — the maintenance PR has no checks to wait for');
756	  }
757	  for (const name of dispatch) {
758	    const res = await gh(token, `/repos/${repo}/actions/workflows/${name}/dispatches`, {
759	      method: 'POST', body: { ref: branch },
760	    });
761	    if (res.status === 204) console.log(`baselining: dispatched ${name} on ${branch} — the maintenance PR gets its checks`);
762	    else console.log(`baselining: could not dispatch ${name} on ${branch} (${res.status})`);
763	  }
764	  return { dispatch, missing };
765	}
766	
767	// Ask the owner to add a repo Actions secret a task declares in `required_secrets`
768	// but the repo has not configured. The wiring converge stamps every declared name
769	// into the scheduler workflow, so by the time this runs the value is either in the
770	// environment or genuinely unset — no separate probe needed.
771	//
772	// This is the adoption interview's posture, not a gate: nothing fails, no check
773	// fires, and the task that needs the secret simply doesn't work until someone adds
774	// it. One open issue per repo (matched by exact title) so an unconfigured secret
775	// costs one issue, not one per night. Exported for the tests.
776	export const SECRETS_ISSUE_TITLE = 'Claudinite: configure required Actions secrets';
777	
778	export function unconfiguredSecrets(declared, env) {
779	  return (declared ?? []).filter((name) => !env[name]);
780	}
781	
782	async function askForSecrets(token, repo, names) {
783	  const q = encodeURIComponent(`repo:${repo} in:title "${SECRETS_ISSUE_TITLE}" state:open`);
784	  const { json } = await gh(token, `/search/issues?q=${q}&per_page=10`);
785	  if ((json?.items ?? []).some((i) => (i.title ?? '').trim() === SECRETS_ISSUE_TITLE)) return false;
786	  const body = [
787	    'A scheduled task in this repo declares a repo **Actions secret** that is not configured yet.',
788	    'Until it is, that task cannot do its work — everything else keeps running normally.',
789	    '',
790	    ...names.map((n) => `- \`${n}\``),
791	    '',
792	    `Add each one at https://github.com/${repo}/settings/secrets/actions, then close this issue.`,
793	  ].join('\n');
794	  await gh(token, `/repos/${repo}/issues`, { method: 'POST', body: { title: SECRETS_ISSUE_TITLE, body } });
795	  return true;
796	}
797	
798	// Arm native auto-merge on a PR (by node id) via the GraphQL mutation — the REST
799	// `PUT /merge` would merge NOW, ignoring pending checks; this waits for them.
800	async function enableAutoMerge(token, pullRequestId) {
801	  const query = 'mutation($id:ID!){enablePullRequestAutoMerge(input:{pullRequestId:$id,mergeMethod:SQUASH}){pullRequest{id}}}';
802	  const res = await fetch(`${API}/graphql`, {
803	    method: 'POST',
804	    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
805	    body: JSON.stringify({ query, variables: { id: pullRequestId } }),
806	  });
807	  const json = await res.json().catch(() => null);
808	  if (json?.errors?.length) throw new Error(json.errors[0].message);
809	}
810	
811	export async function main() {
812	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
813	  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
814	  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
815	  const token = process.env.GITHUB_TOKEN;
816	  const requestFile = process.env.CLAUDINITE_REQUEST_AGENT;
817	  // Set by deliver() to `{ branch, pr, merged }`; stays null when this cycle opened
818	  // nothing, which is what the dispatch issue then says.
819	  let delivered = null;
820	  if (!repo) { console.error('baselining: no repo (CLAUDINITE_REPO/GITHUB_REPOSITORY)'); process.exit(1); }
821	  if (!token) { console.error('baselining: no GITHUB_TOKEN in env'); process.exit(1); }
822	
823	  const checksPath = join(root, '.claudinite-checks.json');
824	  if (!existsSync(checksPath)) { console.log('baselining: no .claudinite-checks.json — nothing to self-refresh'); return; }
825	  const priorRaw = JSON.parse(readFileSync(checksPath, 'utf8'));
826	  const priorStamp = priorRaw.claudinite ?? {};
827	  if (!priorStamp.updated && !priorStamp.ref) {
828	    console.log('baselining: no vendored-mount stamp — nothing to self-refresh (canon home or pre-adoption)');
829	    return; // quiet, no agent (matches the precondition self-skip)
830	  }
831	  const { delivery, materialize } = resolveDelivery(priorRaw?.maintenance?.delivery);
832	  if (!delivery) {
833	    console.error(`baselining: maintenance.delivery "${priorRaw?.maintenance?.delivery}" is neither auto-merge nor review`);
834	    process.exit(1);
835	  }
836	  // Materialize the missing key BEFORE the converge, so the repair rides this
837	  // cycle's maintenance commit like any other converged surface.
838	  if (materialize) {
839	    priorRaw.maintenance = { ...priorRaw.maintenance, delivery };
840	    writeFileSync(checksPath, JSON.stringify(priorRaw, null, 2) + '\n');
841	    console.log(`baselining: maintenance.delivery was missing — materialized "${delivery}"`);
842	  }
843	
844	  // 1. Fetch canon at head as a ROOTLESS tree (drop .git so apply-vendor-set's
845	  //    ancestry guards skip — a shallow clone can't answer them, and it is head
846	  //    by construction).
847	  const source = canonSource(process.env);
848	  const tmp = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
849	  git(source.ref
850	    ? ['clone', '--depth', '1', '--branch', source.ref, source.url, tmp]
851	    : ['clone', '--depth', '1', source.url, tmp]);
852	  const headSha = git(['-C', tmp, 'rev-parse', 'HEAD']).trim();
853	  rmSync(join(tmp, '.git'), { recursive: true, force: true });
854	  if (source.rehearsal) {
855	    console.log(`baselining: REHEARSAL against ${source.url}@${source.ref} (${headSha.slice(0, 8)}) — `
856	      + 'the stamp will be restored, and nothing is delivered');
857	  }
858	
859	  // 2-4. Deterministic converge: mount + stamp, then wiring, then mechanical notes.
860	  node([join(tmp, 'vendoring/apply-vendor-set.mjs'), '--target', root, '--ref', headSha]);
861	  const wiringOut = node([join(tmp, 'engine/scheduler/converge-wiring.mjs'), repo], { CLAUDINITE_REPO_ROOT: root });
862	  // The handshake (migrations/registry.mjs, WITHHOLD_CAPABLE_ENV): THIS worker withholds
863	  // workflow paths from its commit and hands them to the agent, so a record may safely
864	  // materialize one. An older vendored worker does not set it and the materialization is
865	  // skipped instead of wedging its push. Set here, by the code that does the withholding,
866	  // because the question is what the RUNNING process can do — and the disk cannot answer
867	  // it: apply-vendor-set above has already overwritten this very file with the new
868	  // version while this old-or-new code is the thing actually executing.
869	  node([join(tmp, 'migrations/apply.mjs')], { CLAUDE_PROJECT_DIR: root, CLAUDINITE_CAN_WITHHOLD_WORKFLOWS: '1' });
870	
871	  // Ask about any declared secret the repo hasn't configured — but only once the
872	  // wiring is settled. On the cycle that FIRST stamps a name into the workflow the
873	  // value cannot be in this process's env yet, so asking then would nag about a
874	  // secret the owner may well have already added; next cycle tells the truth.
875	  const { declaredSecrets } = await import(pathToFileURL(join(tmp, 'engine/scheduler/converge-wiring.mjs')).href);
876	  const missingSecrets = wiringOut.includes('.github/workflows/claudinite-scheduler.yml')
877	    ? []
878	    : unconfiguredSecrets(await declaredSecrets(root, JSON.parse(readFileSync(checksPath, 'utf8'))), process.env);
879	  if (missingSecrets.length && await askForSecrets(token, repo, missingSecrets)) {
880	    console.log(`baselining: asked the owner to configure ${missingSecrets.join(', ')}`);
881	  }
882	
883	  // 5. Pending agentic notes (from the fresh canon clone) + stamp hold.
884	  const { loadMigrations, agenticMigrations } = await import(pathToFileURL(join(tmp, 'migrations/registry.mjs')).href);
885	  const pending = pendingAgentic(agenticMigrations(await loadMigrations()), priorStamp.updated);
886	  if (pending.length) {
887	    const raw = JSON.parse(readFileSync(checksPath, 'utf8'));
888	    raw.claudinite = { ...raw.claudinite, updated: heldStamp(pending) };
889	    writeFileSync(checksPath, JSON.stringify(raw, null, 2) + '\n');
890	  }
891	
892	  // 6. Meaningful change? A stamp-only bump against an unchanged head is not one —
893	  //    revert it and stay quiet (no nightly stamp-only noise).
894	  const changed = git(['-C', root, 'status', '--porcelain'])
895	    .split('\n').map((l) => l.slice(3)).filter(Boolean);
896	  // `materialize` excluded: a materialized delivery key also touches only
897	  // .claudinite-checks.json, and reverting it would re-drift the repo every night
898	  // and never land the repair.
899	  const onlyStamp = changed.length > 0 && !materialize && changed.every((p) => p === '.claudinite-checks.json');
900	  if (onlyStamp && priorStamp.ref === headSha && !pending.length) {
901	    git(['-C', root, 'checkout', '--', '.claudinite-checks.json']);
902	    console.log('baselining: mount already at canon head, nothing changed — agentless, quiet');
903	    return;
904	  }
905	  const meaningfulChange = changed.length > 0;
906	  // What this stage cannot push. Computed here, before the escalation gate, because a
907	  // withheld file is residual work for the agent exactly like a pending agentic note.
908	  const withheld = withheldWorkflowPaths(changed);
909	  if (withheld.length) {
910	    console.log(`baselining: withholding ${withheld.length} workflow file(s) from the push — `
911	      + `the Action token cannot write .github/workflows/; the agent stage lands them: ${withheld.join(', ')}`);
912	  }
913	
914	  // 6b. SELF-TEST the converged tree before judging its content. This asks "can
915	  //     Claudinite still run here?" — mount, stamp, pack manifests, hook targets,
916	  //     mounted skills, cron, migrations registry — and it is the gate that would
917	  //     have caught #555 the night it landed: a required manifest field arrived
918	  //     with no migration, every consumer pack stopped validating, and because a
919	  //     pack that fails validation contributes NO rules, check_the_world went on
920	  //     reporting green about a corpus it was no longer running. A content check
921	  //     cannot see its own machinery break. This runs on the just-converged tree,
922	  //     so it judges what the member is about to live with.
923	  const selftest = runSelfTest(root);
924	  if (!selftest.ok) {
925	    console.log('baselining: the converged mount FAILED its self-test — requesting the agent');
926	    logGateOutput('selftest --strict', selftest);
927	  }
928	
929	  // 7. Escalation gate: run the conformance checks only when a change happened and
930	  //    no agentic note already forces the agent. A failed self-test forces it too:
931	  //    broken machinery is exactly the judgment case, and merging it would spread
932	  //    the breakage to a repo that was working an hour ago.
933	  const checks = (meaningfulChange && !pending.length) ? runCheckTheWorld(root) : GATE_ABSENT;
934	  if (!checks.ok) logGateOutput('check_the_world', checks);
935	  const reason = escalation({
936	    pendingCount: pending.length, meaningfulChange, checksPass: checks.ok, selftestOk: selftest.ok,
937	    withheldCount: withheld.length, checksCrashed: checks.crashed, selftestCrashed: selftest.crashed,
938	  });
939	  const requestAgent = reason !== null;
940	
941	  // 7b. A REHEARSAL stops here. It has done the only thing it was for — converged
942	  //     this real repo against a canon BRANCH and asked whether the result still
943	  //     works — and now it must leave no trace: no commit, no branch, no PR, and
944	  //     above all no stamp. Stamping a branch head would leave the member
945	  //     `ref-not-on-trunk`, which the #328 anti-rewind guard then refuses to
946	  //     converge over: a rehearsal that wedged the repo it was rehearsing on.
947	  //     `git checkout -- .` restores the working tree wholesale, so the mount goes
948	  //     back to the vendored snapshot the repo actually runs.
949	  if (source.rehearsal) {
950	    git(['-C', root, 'checkout', '--', '.']);
951	    const verdict = selftest.ok && checks.ok ? 'PASS' : 'FAIL';
952	    console.log(`baselining: rehearsal ${verdict} — selftest ${selftest.ok ? 'ok' : 'FAILED'}, `
953	      + `checks ${checks.ok ? 'green' : 'RED'}, ${changed.length} file(s) would have changed. Working tree restored.`);
954	    if (verdict === 'FAIL') process.exit(1);   // the canary's whole purpose: fail the canon PR
955	    return;
956	  }
957	
958	  // 8. Deliver the converge (only when there's something to land).
959	  if (meaningfulChange || pending.length) {
960	    const seed = Math.random().toString(36).slice(2, 8);
961	    delivered = await deliver(root, repo, base, token, delivery, seed, withheld);
962	    console.log(`baselining: delivered converge on ${delivered.branch}${delivered.pr ? ` (PR #${delivered.pr}${delivered.merged ? ', merged' : ''})` : ''} (${delivery})`);
963	  } else {
964	    console.log('baselining: no change to deliver');
965	  }
966	
967	  // 9. Request the agent only when judgment is left (conditional handoff, §3) — naming
968	  //    what this run created AND why the agent is being woken. `delivered` stays null
969	  //    when nothing was opened, and the issue then names nothing; `reason` is non-null
970	  //    exactly when the agent is requested at all.
971	  if (requestAgent && requestFile) {
972	    writeFileSync(requestFile, `${JSON.stringify({ marker: AGENT_REQUEST_MARKER, delivered, reason })}\n`);
973	  }
974	  console.log(requestAgent
975	    ? `baselining: requested agent stage (${reason.code}: ${reason.detail})`
976	    : 'baselining: agentless night — deterministic converge delivered, no agent needed');
977	}
978	
979	// Run only when invoked directly (the scheduler's `node worker.mjs`), never on
980	// import — a test imports the pure helpers without any git or network.
981	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
982	  main().catch((e) => { console.error(`baselining preprocessing failed: ${e.message}`); process.exit(1); });
983	}
